import{_ as o,o as i,c,a2 as a}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0043 — Convergenza degli stack UI di console e workbench","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0043-convergenza-ui-console-workbench.md","filePath":"adr/0043-convergenza-ui-console-workbench.md"}'),n={name:"adr/0043-convergenza-ui-console-workbench.md"};function d(t,e,s,l,r,u){return i(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0043-—-convergenza-degli-stack-ui-di-console-e-workbench" tabindex="-1">ADR-0043 — Convergenza degli stack UI di console e workbench <a class="header-anchor" href="#adr-0043-—-convergenza-degli-stack-ui-di-console-e-workbench" aria-label="Permalink to &quot;ADR-0043 — Convergenza degli stack UI di console e workbench&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.7 (Web UI), §2.x (client desktop); D-01, V-02 (architettura chiusa); ADR-0025, ADR-0029, ADR-0037</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La revisione W8 (finding <code>duplicate-ui-systems</code>) ha rilevato che la Web UI ha due stack di interfaccia separati:</p><table tabindex="0"><thead><tr><th>Aspetto</th><th>Console (<code>web/src</code>, <code>packages/cloud-features</code>)</th><th>Workbench (<code>packages/workbench</code>, desktop e browser)</th></tr></thead><tbody><tr><td>Componenti</td><td><code>@memobrain/ui</code> (<code>components.tsx</code>): <code>Button</code>, <code>Badge</code>, <code>TextField</code>, <code>SelectField</code>, <code>Table</code>, <code>Card</code>, <code>Dialog</code>, <code>ToastProvider</code>, <code>QuotaBar</code>…</td><td><code>ui/dialogs.tsx</code> (API imperativa <code>dialog.prompt/confirm/alert/pick</code> con <code>DialogHost</code> e coda), <code>ui/ContextMenu.tsx</code>, componenti propri di ogni area</td></tr><tr><td>Focus dei modali</td><td><code>Dialog</code> intrappola il Tab e gestisce Escape nel proprio <code>onKeyDown</code></td><td><code>ui/modalFocus.ts</code>: un solo gestore installato sul documento per ogni <code>[aria-modal=&quot;true&quot;]</code> (Tab ciclico sul modale in cima, ritorno del focus all&#39;opener tramite MutationObserver)</td></tr><tr><td>Stile</td><td><code>@memobrain/ui/styles.css</code> e <code>components.css</code> (classi <code>nd-…</code>), CSP senza stili inline</td><td><code>style.css</code> e <code>styles/*</code> globali dell&#39;app desktop; la CSP del workbench ammette stili inline (CodeMirror, KaTeX, Excalidraw)</td></tr><tr><td>i18n</td><td><code>web/src/i18n/{en,it}.json</code>; <code>packages/cloud-features/src/i18n.ts</code> (risorse proprie, unite dall&#39;host); <code>web/src/workbench/strings.ts</code> (tabella EN/IT della pagina di avvio del workbench, fuori dal test di consistenza)</td><td><code>packages/workbench/src/i18n/{en,it}.json</code></td></tr><tr><td>Controllo delle chiavi</td><td><code>packages/ui/src/i18nCheck.ts</code>, importato con percorsi relativi da tre test (web, workbench, cloud-features)</td><td>idem</td></tr></tbody></table><p>Le due metà non sono più isolate come all&#39;inizio: con ADR-0037 i pannelli di <code>@memobrain/cloud-features</code> (che usano <code>@memobrain/ui</code>) girano anche <strong>dentro</strong> il workbench, sul desktop e nel browser. Nel workbench convivono quindi due gestioni del focus dei modali (quella del <code>Dialog</code> di <code>@memobrain/ui</code> e quella globale di <code>modalFocus.ts</code>) e due insiemi di classi e token di stile. Una correzione di accessibilità, di focus o di tema fatta da una parte non arriva all&#39;altra, e la parità desktop/web (ADR-0029) ne risente.</p><p>Vincoli che restano:</p><ul><li>la console mantiene la CSP stretta (<code>style-src &#39;self&#39;</code>, nessuno stile inline) e il suo budget (700 kB iniziali, ADR-0020/0025);</li><li>lo stile globale del workbench non deve toccare la console (ADR-0029: pagine separate);</li><li>architettura chiusa (D-01, V-02): niente temi di terze parti o librerie di componenti esterne con CSS proprio;</li><li>il workbench è lo stesso codice sul desktop (Wails) e nel browser.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p>Si propone di far convergere i due stack sulle <strong>primitive</strong> (comportamento e accessibilità), non sull&#39;aspetto né sull&#39;intera libreria di componenti. <code>@memobrain/ui</code> diventa il pacchetto delle primitive senza stile globale, consumato da console, cloud-features e workbench. I passi, in ordine di rischio crescente, ognuno rilasciabile da solo:</p><ol><li><strong><code>i18nCheck</code> come entry del pacchetto</strong> — fatto: <code>@memobrain/ui/i18nCheck</code> (<code>exports</code> di <code>packages/ui/package.json</code>). I tre test di consistenza possono importarlo dal pacchetto invece che con <code>../../../ui/src/i18nCheck</code> (cambio meccanico, da fare dai rispettivi owner).</li><li><strong>Un solo meccanismo di focus dei modali.</strong> <code>modalFocus.ts</code> si sposta in <code>packages/ui/src/focus.ts</code> (stessa API <code>installModalFocus</code>, già indipendente da React e dal workbench). Il <code>Dialog</code> di <code>@memobrain/ui</code> smette di intrappolare il Tab da sé quando l&#39;host ha installato il gestore globale (o lo installa al primo montaggio), così nel workbench c&#39;è un solo comportamento. Test: quelli di <code>modalFocus</code> e di <code>components.test.tsx</code> passano in <code>packages/ui</code>; gli e2e <code>keyboard</code>/<code>a11y</code> del desktop e della console restano invariati.</li><li><strong>Primitive di menu e di dialog imperativo.</strong> Il comportamento da tastiera di <code>ContextMenu</code> (frecce, Home/End, Escape, chiusura al click esterno) diventa un hook <code>useMenuKeyboard</code> in <code>@memobrain/ui</code>; <code>dialog.prompt/confirm/alert/pick</code> restano l&#39;API del workbench ma rendono attraverso il <code>Dialog</code> di <code>@memobrain/ui</code> (le classi del workbench restano come varianti). La console guadagna <code>confirm</code> imperativo senza duplicarlo.</li><li><strong>Token di stile condivisi.</strong> Le custom property (colori, spaziature, raggi, focus ring) passano in un <code>tokens.css</code> di <code>@memobrain/ui</code>, importato sia da <code>styles.css</code> della console sia da <code>style.css</code> del workbench; i componenti di <code>@memobrain/ui</code> usano solo classi con prefisso (<code>nd-…</code>) e token, mai selettori globali e mai stili inline (la CSP della console non li ammette). Il tema scuro/chiaro si governa con gli stessi token.</li><li><strong>Un namespace i18n comune.</strong> Le stringhe uguali nei due mondi (OK, Annulla, Chiudi, Riprova, i messaggi <code>errors.&lt;code&gt;</code> dell&#39;API) vanno in <code>@memobrain/ui/i18n/{en,it}.json</code> (namespace <code>common</code>), aggiunte da ogni host alla propria istanza di i18next. <code>web/src/workbench/strings.ts</code> passa nei JSON della Web UI sotto <code>workbench.*</code>, coperto dal test di consistenza (è anche il passo 3 del finding <code>duplicated-console-workbench-logic</code>).</li></ol><p>Non si propone di spostare in <code>@memobrain/ui</code> i componenti specifici del workbench (editor, albero, pannelli) né di adottare una libreria esterna (Radix, Headless UI…): porterebbe dipendenze e CSS di terze parti contro V-02 e non risolve la differenza di CSP tra le due pagine.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Lasciare i due stack separati</strong> — costo nullo oggi, ma il workbench contiene già componenti di entrambi (cloud-features) e i fix di accessibilità vanno fatti due volte. Scartata.</li><li><strong>Workbench su <code>@memobrain/ui</code> per intero</strong> (tutti i componenti, un solo CSS) — il CSS globale del workbench entrerebbe nella console o andrebbe riscritto per intero; rischio alto su desktop e web, beneficio non proporzionato. Scartata.</li><li><strong>Console sui componenti del workbench</strong> — porterebbe nella console dipendenze pesanti (zustand, i18n del workbench) e stili globali, contro il budget e l&#39;isolamento di ADR-0029. Scartata.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Un solo punto per focus trap, menu da tastiera e dialoghi: le regressioni di accessibilità si correggono una volta e si verificano con i test di <code>packages/ui</code> più gli e2e esistenti.</li><li>Il bundle della console non cresce in modo apprezzabile (le primitive sono poche centinaia di righe senza dipendenze); va controllato con <code>checkBudget</code> a ogni passo.</li><li>I passi 2–5 toccano codice di più owner (workbench, cloud-features, console): vanno pianificati come work package con gli e2e desktop (<code>task e2e</code>), console (<code>task e2e-web</code>) e workbench web (<code>e2e:workbench-ui</code>) verdi a ogni passo.</li><li>Da rivedere dopo il passo 4: se i token bastano a uniformare l&#39;aspetto, o se serve una guida di stile scritta in <code>docs/</code>.</li></ul><h2 id="esito" tabindex="-1">Esito <a class="header-anchor" href="#esito" aria-label="Permalink to &quot;Esito&quot;">​</a></h2><p>Implementazione al 2026-11-02 dei passi 1–5, ognuno senza cambiare l&#39;aspetto delle due pagine (le classi del workbench restano quelle di prima, i token del workbench hanno i suoi valori).</p><ol><li><strong><code>i18nCheck</code> dal pacchetto.</strong> I tre test di consistenza importano <code>@memobrain/ui/i18nCheck</code> (<code>web/src/i18n/consistency.test.ts</code>, <code>packages/workbench/src/i18n/consistency.test.ts</code>, <code>packages/cloud-features/src/i18n.test.ts</code>). <code>i18nCheck.ts</code> ha in più <code>withShared</code> (risorse dell&#39;host con quelle comuni sovrapposte, come le risolve i18next) e <code>overlap</code> (chiavi comuni ridefinite da un host).</li><li><strong>Un solo gestore del focus dei modali.</strong> <code>packages/workbench/src/ui/modalFocus.ts</code> è diventato <code>packages/ui/src/focus.ts</code> (export <code>installModalFocus</code>, più <code>ensureModalFocus</code> e <code>hasModalFocus</code>; entry <code>@memobrain/ui/focus</code>). Il gestore è uno per documento: più installazioni lo condividono. Il <code>Dialog</code> di <code>@memobrain/ui</code> non intrappola più il Tab né restituisce il focus da sé: al montaggio chiama <code>ensureModalFocus</code>, che usa il gestore già installato dal workbench (<code>app/App.tsx</code>) o lo installa nella console, e registra subito il dialogo, così l&#39;opener è noto anche se il dialogo si chiude prima del MutationObserver. Il ritorno del focus è più preciso di prima: si ricorda una breve cronologia dei focus, quindi un dialogo aperto da un controllo di un altro modale (una conferma sopra le impostazioni) restituisce il focus a quel controllo, e un opener rimosso nel frattempo viene saltato a favore del precedente; resta la regola di ADR-0024 (un dialogo aperto da un comando della palette tiene il focus). Il <code>Dialog</code> non sposta più il focus sul primo controllo se un controllo interno l&#39;ha già preso (<code>autoFocus</code>). Test: <code>packages/ui/src/focus.test.ts</code> (ciclo del Tab, ritorno all&#39;opener, dialoghi annidati, palette → comando, condivisione del gestore) e <code>components.test.tsx</code>.</li><li><strong>Primitive di menu e di dialog imperativo.</strong> <code>useMenuKeyboard</code> (<code>packages/ui/src/menu.ts</code>): focus sul primo elemento abilitato e ritorno all&#39;opener, frecce con giro, Home/End, chiusura con Escape, Tab, pressione fuori dal menu e perdita di focus della finestra. <code>ui/ContextMenu.tsx</code> del workbench lo usa (resta suo solo il posizionamento). La console non ha menu, quindi nessun altro consumatore per ora. <code>dialog.prompt/confirm/alert/pick</code> mantengono l&#39;API e la coda, ma <code>DialogHost</code> (<code>ui/dialogs.tsx</code>) rende attraverso il <code>Dialog</code> di <code>@memobrain/ui</code>, che ha ora le opzioni <code>classNames</code> (le classi <code>modal-backdrop</code> / <code>modal dialog</code> del workbench al posto di quelle <code>nd-…</code>), <code>closeOnBackdrop</code> e <code>onKeyDown</code> (Invio per confermare, gestito prima di Escape); il nome accessibile viene dal titolo (<code>aria-labelledby</code>). Il <code>confirm</code> imperativo nella console non è stato aggiunto: oggi non serve, e quando servirà basterà un host di coda sopra lo stesso <code>Dialog</code>. Test: <code>packages/ui/src/menu.test.tsx</code>, <code>components.test.tsx</code>, i test del workbench che usano <code>DialogHost</code>, gli e2e <code>keyboard</code>/<code>a11y</code>.</li><li><strong>Token condivisi.</strong> <code>packages/ui/src/tokens.css</code> (entry <code>@memobrain/ui/tokens.css</code>) contiene solo custom property: forma e spaziatura (<code>--nd-radius</code>, <code>--nd-gap</code>, <code>--nd-space-1…4</code>), carattere, focus ring (<code>--nd-focus</code>, <code>--nd-focus-width</code>, <code>--nd-focus-offset</code>) e la tavolozza della console chiara/scura con lo stesso interruttore <code>data-theme</code> del workbench. <code>styles.css</code> della console lo importa (tiene <code>color-scheme</code> e le regole globali della pagina); <code>components.css</code> usa solo classi <code>nd-…</code> e token (gap e margini sulla scala <code>--nd-space-*</code>, con gli stessi valori di prima). <code>packages/workbench/src/style.css</code> importa <code>@memobrain/ui/tokens.css</code> prima di <code>styles/tokens.css</code>, che assegna ai token <code>--nd-*</code> i valori del workbench su <code>&lt;body&gt;</code> (vincono su <code>:root</code> per ereditarietà) e disegna il proprio focus ring con gli stessi token (offset −2px come prima). La mappatura per <code>.mbcf</code> in <code>packages/cloud-features/src/workbench.css</code> è stata tolta: restano solo densità e contrasto dei testi di stato. Nessuno stile inline nuovo; la CSP della console è invariata (<code>e2e:security</code> verde).</li><li><strong>Namespace i18n comune.</strong> <code>packages/ui/src/i18n/{en,it}.json</code> contiene <code>common.{ok,cancel,close,retry,error}</code> e i messaggi <code>errors.&lt;code&gt;</code> dell&#39;API (UNAUTHENTICATED, FORBIDDEN, USER_SUSPENDED, NOT_FOUND, QUOTA_EXCEEDED, FILE_TOO_LARGE, RATE_LIMITED, VAULT_ENCRYPTED, NAME_IN_USE, INVALID_STATE, INTERNAL). <code>withCommon</code> (<code>packages/ui/src/i18n.ts</code>, entry <code>@memobrain/ui/i18n</code>) li aggiunge a ogni istanza di i18next come namespace <code>common</code> impostato come <code>fallbackNS</code>: i componenti continuano a chiamare <code>t(&#39;common.cancel&#39;)</code> / <code>t(&#39;errors.FORBIDDEN&#39;)</code> e una chiave dell&#39;host vince. Lo usano <code>web/src/i18n/index.ts</code> e <code>packages/workbench/src/i18n/index.ts</code>; dai loro JSON sono state tolte le copie (<code>common.cancel/retry</code>, <code>vaultExport.cancel/close</code> e i codici nella console; <code>dialog.ok/cancel/error</code>, <code>settings.close</code>, <code>importer.cancel/close</code>, <code>updater.close</code>, <code>bases.cancel</code> e i codici maiuscoli nel workbench; i codici minuscoli dei binding restano del workbench). Il testo di <code>errors.NOT_FOUND</code> nella console è ora quello del workbench («…on the server…»). <code>web/src/workbench/strings.ts</code> legge i testi della pagina del workbench da <code>web/src/i18n/{en,it}.json</code> sotto <code>workbench.*</code> (segnaposto <code>{{count}}</code>), più Retry/Annulla da quelli comuni, con import nominali dai JSON perché il resto delle risorse della console non entri nel bundle della pagina; le chiamate usano la chiave completa (<code>message(&#39;workbench.locking&#39;)</code>), così il controllo d&#39;uso le vede. I test di consistenza verificano anche che nessun host ridefinisca una chiave comune; <code>@memobrain/cloud-features</code> resta con il proprio dizionario (non usa i18next).</li></ol><p>Bundle (<code>task web-build</code>): console iniziale 664 → 675 kB (limite 700), workbench iniziale 2466 → 2472 kB (limite 2500). La misura «dopo» comprende anche lavori paralleli sullo stesso albero (condivisioni, ADR-0041); la parte di questo ADR è stimata in circa 7 kB per la console (i testi <code>workbench.*</code> e quelli comuni nelle risorse della console, <code>focus.ts</code>).</p><p>Da fare dopo: aggiornare <code>docs/qa/i18n-glossary.md</code> (namespace comune); decidere se i token bastano o se serve una guida di stile scritta.</p>',21)])])}const g=o(n,[["render",d]]);export{m as __pageData,g as default};
